"""Plots generated by the MAE-style pipeline (Professional Version).

CORRECTED + EXTENDED VERSION:
  - t-SNE colour arrays aligned to per-object embeddings.
  - Per-object aggregation before calling t-SNE plotting functions.
  - Shape guards raise clear errors when misalignment is detected.
  - plot_r2_scatter_diagnostic builds its x-axis from the masked array length.

  NEW plots added (13-16):
    13. Per-object flux bias vs. TRUE total detection flux (log-x scatter)
    14. Flux-binned bias diagnostic (mean ± SEM and median vs flux)
    15. t-SNE coloured by sin(RA)
    16. t-SNE coloured by scaled DEC
"""

import matplotlib.pyplot as plt
import numpy as np
from sklearn.manifold import TSNE
from sklearn.metrics import r2_score
import logging
from matplotlib.colors import LogNorm, SymLogNorm
from matplotlib.gridspec import GridSpec

logger = logging.getLogger(__name__)


# ==============================================================================
# Helper Functions for Styling and Normalization
# ==============================================================================

def make_true_flux_norm(values):
    """Log colour normalisation using the 1st-99th percentile of positive flux."""
    v = np.asarray(values)
    v = v[np.isfinite(v)]
    pos = v[v > 0]
    if len(pos) >= 10:
        vmin = max(np.nanpercentile(pos, 1), 1e-12)
        vmax = np.nanpercentile(pos, 99)
        return LogNorm(vmin=vmin, vmax=vmax if vmax > vmin else vmin * 1.01, clip=True)
    if len(v) == 0:
        return SymLogNorm(linthresh=1e-3, vmin=-1.0, vmax=1.0, clip=True)
    return SymLogNorm(
        linthresh=1e-3,
        vmin=np.nanpercentile(v, 1),
        vmax=np.nanpercentile(v, 99),
        clip=True,
    )


def r2_safe(y_true, y_pred):
    """Safely compute R^2 score (returns NaN if undefined)."""
    y_true = np.asarray(y_true, dtype=np.float64)
    y_pred = np.asarray(y_pred, dtype=np.float64)
    finite = np.isfinite(y_true) & np.isfinite(y_pred)
    y_true, y_pred = y_true[finite], y_pred[finite]
    if len(y_true) < 2:
        return np.nan
    ss_res = np.sum((y_true - y_pred) ** 2)
    ss_tot = np.sum((y_true - np.mean(y_true)) ** 2)
    if ss_tot <= 1e-14:
        return np.nan
    return 1.0 - ss_res / ss_tot


def _aggregate_per_object(object_ids, values):
    """Aggregate a per-sample array into a per-object array (mean per object)."""
    object_ids = np.asarray(object_ids)
    values = np.asarray(values, dtype=float)
    unique_ids = np.unique(object_ids)
    per_object = np.full(len(unique_ids), np.nan, dtype=float)
    for i, oid in enumerate(unique_ids):
        m = (object_ids == oid)
        if m.sum() > 0:
            per_object[i] = np.nanmean(values[m])
    return per_object, unique_ids


# ==============================================================================
# Plotting Functions
# ==============================================================================

def plot_r2_scatter_diagnostic(
    y_values, true_flux, n_val, y_label, panel_letter, filename,
    output_directory, n_bins_rolling=60
):
    """Scientific SCATTER diagnostic for per-object R^2."""
    y_values = np.asarray(y_values, dtype=float)
    true_flux = np.asarray(true_flux, dtype=float)

    if y_values.shape[0] != true_flux.shape[0]:
        raise ValueError(
            f"[plot_r2_scatter_diagnostic] shape mismatch for '{filename}': "
            f"y_values has {y_values.shape[0]} entries but "
            f"true_flux has {true_flux.shape[0]}."
        )

    mask = np.isfinite(y_values) & np.isfinite(true_flux) & (true_flux > 0)
    if mask.sum() < 2:
        logger.warning(
            f"[plot_r2_scatter_diagnostic] Not enough valid points for '{filename}' "
            f"({mask.sum()} valid). Skipping."
        )
        return

    x = np.arange(len(y_values))[mask]
    y = y_values[mask]
    c = true_flux[mask]

    y_lo, y_hi = np.nanpercentile(y, [1, 99])
    pad = 0.05 * (y_hi - y_lo)
    y_lim = (y_lo - pad, y_hi + pad)

    # Rolling median and IQR
    bin_edges = np.linspace(x.min(), x.max() + 1, n_bins_rolling + 1)
    bin_centers = 0.5 * (bin_edges[:-1] + bin_edges[1:])
    medians = np.full(n_bins_rolling, np.nan)
    q25 = np.full(n_bins_rolling, np.nan)
    q75 = np.full(n_bins_rolling, np.nan)
    for i in range(n_bins_rolling):
        sel = (x >= bin_edges[i]) & (x < bin_edges[i + 1])
        if sel.sum() >= 10:
            medians[i] = np.median(y[sel])
            q25[i], q75[i] = np.percentile(y[sel], [25, 75])

    fig = plt.figure(figsize=(13, 6.5))
    gs = GridSpec(1, 2, width_ratios=[4.5, 1.1], wspace=0.06,
                  left=0.07, right=0.97, top=0.90, bottom=0.11)
    ax_main = fig.add_subplot(gs[0, 0])
    ax_hist = fig.add_subplot(gs[0, 1], sharey=ax_main)

    # LAYER 1: All objects (muted)
    true_flux_norm = make_true_flux_norm(c)
    sc_bg = ax_main.scatter(
        x, y, c=c, s=3, alpha=0.25, cmap="inferno",
        norm=true_flux_norm, edgecolors="none", rasterized=True, zorder=1,
    )

    # LAYER 2: Highlight top 10% brightest (Golden Yellow)
    threshold = np.percentile(c, 90)
    highlight_mask = c >= threshold
    ax_main.scatter(
        x[highlight_mask], y[highlight_mask],
        c="#FFD700", s=7, alpha=0.9, edgecolors="none", zorder=5,
        label="Top 10% brightest flux",
    )

    # Overlays
    ax_main.fill_between(bin_centers, q25, q75, color="white", alpha=0.35,
                         lw=0, zorder=3, label="IQR (25–75%)")
    ax_main.plot(bin_centers, medians, color="black", lw=2.0, zorder=4,
                 label="Median")
    ax_main.axhline(0.0, color="red", ls="--", lw=1.2, alpha=0.85, zorder=5)

    ax_main.set_xlim(x.min(), x.max())
    ax_main.set_ylim(*y_lim)
    ax_main.set_xlabel("Validation object index")
    ax_main.set_ylabel(y_label)
    ax_main.set_title(f"({panel_letter}) {filename}", loc="left")
    ax_main.grid(alpha=0.12, zorder=0)
    ax_main.legend(loc="lower right", frameon=True, facecolor="white",
                   framealpha=0.9, fontsize=9)

    cb = fig.colorbar(sc_bg, ax=ax_main, pad=0.01, fraction=0.045)
    cb.set_label("TRUE total detection flux\n(log scale, 1–99%)")

    # Horizontal Marginal
    counts, bin_edges_hist = np.histogram(np.clip(y, *y_lim), bins=60)
    bin_centers_hist = (bin_edges_hist[:-1] + bin_edges_hist[1:]) / 2
    ax_hist.barh(bin_centers_hist, counts,
                 height=(bin_edges_hist[1] - bin_edges_hist[0]) * 0.9,
                 color="steelblue", alpha=0.85, edgecolor="white", linewidth=0.3)
    ax_hist.axhline(0.0, color="red", ls="--", lw=1.2, alpha=0.85)
    ax_hist.set_xlabel("Count")
    ax_hist.tick_params(labelleft=False)
    ax_hist.grid(alpha=0.15, axis="x")
    ax_hist.set_title("Marginal", fontsize=11)
    ax_hist.spines['top'].set_visible(False)
    ax_hist.spines['right'].set_visible(False)
    ax_hist.spines['left'].set_visible(False)

    # Summary statistics
    n_total = len(y)
    frac_pos = 100.0 * np.sum(y > 0) / n_total
    med_all = np.median(y)
    summary = (f"$N = {n_total:,}$\n"
               f"median $R^2 = {med_all:.3f}$\n"
               f"$R^2 > 0$: {frac_pos:.1f}%")
    ax_main.text(0.02, 0.97, summary, transform=ax_main.transAxes,
                 va="top", ha="left", fontsize=10,
                 bbox=dict(boxstyle="round,pad=0.4", fc="white",
                           ec="0.7", alpha=0.92))

    fig.savefig(output_directory / f"{filename}.png", dpi=300)
    fig.savefig(output_directory / f"{filename}.pdf")
    plt.close(fig)


def plot_tsne_with_marginal(
    embedding_2d, colour_values, label, filename, output_directory,
    flux_scale=False, bins=25, cmap="inferno", dark_background=True
):
    """
    t-SNE scatter coloured by a physical quantity + horizontal marginal.

    Parameters
    ----------
    embedding_2d    : (N_obj, 2) array — t-SNE coordinates.
    colour_values   : (N_obj,) array — value per object.
    label           : str — colourbar label.
    filename        : str — output filename (without extension).
    output_directory: Path
    flux_scale      : bool — if True, uses log norm + highlights top 10%.
    bins            : int — number of bins for the marginal histogram.
    cmap            : str — matplotlib colormap name.
    dark_background : bool — dark mode for the scatter axes.
    """
    embedding_2d = np.asarray(embedding_2d)
    colour_values = np.asarray(colour_values, dtype=float)

    if embedding_2d.shape[0] != colour_values.shape[0]:
        raise ValueError(
            f"[plot_tsne_with_marginal] shape mismatch for '{filename}': "
            f"embedding_2d has {embedding_2d.shape[0]} rows but "
            f"colour_values has {colour_values.shape[0]} rows."
        )

    c = colour_values
    finite = np.isfinite(c)

    if finite.sum() < 2:
        logger.warning(f"[plot_tsne_with_marginal] Not enough finite values for '{filename}'.")
        return

    x = embedding_2d[finite, 0]
    y = embedding_2d[finite, 1]
    c_clean = c[finite]

    norm = make_true_flux_norm(c_clean) if flux_scale else None

    fig, (ax_scatter, ax_hist) = plt.subplots(
        1, 2, figsize=(15, 6.5),
        gridspec_kw={"width_ratios": [3, 1], "wspace": 0.06},
    )

    if dark_background:
        ax_scatter.set_facecolor('#1a1a1a')
        text_color = 'white'
    else:
        ax_scatter.set_facecolor('white')
        text_color = 'black'

    # LAYER 1: Muted background
    sc_bg = ax_scatter.scatter(
        x, y, c=c_clean, s=10, alpha=0.4, cmap=cmap,
        norm=norm, edgecolors="none", zorder=1,
    )

    # LAYER 2: Highlight top 10% brightest if flux_scale
    if flux_scale:
        threshold = np.percentile(c_clean, 90)
        highlight_mask = c_clean >= threshold
        ax_scatter.scatter(
            x[highlight_mask], y[highlight_mask],
            c="#FFD700", s=12, alpha=0.9, edgecolors="none", zorder=5,
            label="Top 10% brightest flux",
        )
        ax_scatter.legend(loc="upper right", frameon=True, facecolor='white',
                          framealpha=0.9, fontsize=9)

    ax_scatter.set_xlabel("t-SNE component 1", color=text_color)
    ax_scatter.set_ylabel("t-SNE component 2", color=text_color)
    ax_scatter.set_title(filename, loc="left", color=text_color)
    ax_scatter.tick_params(colors=text_color)

    cb = fig.colorbar(sc_bg, ax=ax_scatter, pad=0.01, fraction=0.045)
    if flux_scale:
        cb.set_label(label + "\n(log scale, 1–99%)", color=text_color)
    else:
        cb.set_label(label, color=text_color)
    cb.ax.yaxis.set_tick_params(color=text_color)
    cb.outline.set_edgecolor(text_color)
    ax_scatter.grid(alpha=0.15, color='gray')

    # Horizontal Marginal
    counts, bin_edges = np.histogram(c_clean, bins=bins)
    percentages = (counts / len(c_clean)) * 100
    bin_centers = (bin_edges[:-1] + bin_edges[1:]) / 2
    ax_hist.barh(bin_centers, percentages,
                 height=(bin_edges[1] - bin_edges[0]) * 0.8,
                 color="#ff7f0e", alpha=0.9, edgecolor="white", linewidth=0.3)
    ax_hist.set_xlabel("Fraction of objects (%)")
    ax_hist.tick_params(labelleft=False)
    ax_hist.set_title("Marginal", fontsize=11)
    ax_hist.grid(alpha=0.15, axis="x")
    ax_hist.spines['top'].set_visible(False)
    ax_hist.spines['right'].set_visible(False)
    ax_hist.spines['left'].set_visible(False)

    fig.tight_layout()
    fig.savefig(output_directory / f"{filename}.png", dpi=300)
    fig.savefig(output_directory / f"{filename}.pdf")
    plt.close(fig)


def plot_3d_tsne(embedding_3d, true_flux, output_directory,
                 filename="12_tsne_3d_flux"):
    """3D t-SNE coloured by TRUE flux."""
    embedding_3d = np.asarray(embedding_3d)
    true_flux = np.asarray(true_flux, dtype=float)

    if embedding_3d.shape[0] != true_flux.shape[0]:
        raise ValueError(
            f"[plot_3d_tsne] shape mismatch: embedding_3d has "
            f"{embedding_3d.shape[0]} rows but true_flux has "
            f"{true_flux.shape[0]} rows."
        )

    fig = plt.figure(figsize=(10, 8))
    ax = fig.add_subplot(111, projection='3d')
    sc = ax.scatter(
        embedding_3d[:, 0], embedding_3d[:, 1], embedding_3d[:, 2],
        c=true_flux, s=10, alpha=0.6, cmap='inferno',
        norm=make_true_flux_norm(true_flux),
    )
    ax.set_title("3D t-SNE of CLS embeddings — coloured by TRUE flux", fontsize=14)
    ax.set_xlabel("t-SNE 1")
    ax.set_ylabel("t-SNE 2")
    ax.set_zlabel("t-SNE 3")
    cb = fig.colorbar(sc, ax=ax, shrink=0.6)
    cb.set_label("TRUE total flux (log scale)")
    fig.tight_layout()
    fig.savefig(output_directory / f"{filename}.png", dpi=300)
    plt.close(fig)


# ------------------------------------------------------------------------------
# NEW PLOT 13: Per-object flux bias vs. TRUE total detection flux
# ------------------------------------------------------------------------------
def plot_per_object_bias_vs_true_flux(
    true_flux_per_obj, mean_residual_per_obj, output_directory,
    filename="13_per_object_bias_vs_true_flux"
):
    """
    Scatter of per-object mean residual (bias) versus TRUE total detection flux.
    - x-axis: log scale
    - color: same as x (TRUE flux), so we can visually track density
    - horizontal red dashed line at y = 0
    """
    true_flux_per_obj = np.asarray(true_flux_per_obj, dtype=float)
    mean_residual_per_obj = np.asarray(mean_residual_per_obj, dtype=float)

    # Keep only positive flux for log-x and finite residuals
    mask = (np.isfinite(true_flux_per_obj) &
            np.isfinite(mean_residual_per_obj) &
            (true_flux_per_obj > 0))
    if mask.sum() < 2:
        logger.warning("[plot_per_object_bias_vs_true_flux] Not enough points. Skipping.")
        return

    x = true_flux_per_obj[mask]
    y = mean_residual_per_obj[mask]

    fig, ax = plt.subplots(figsize=(12, 7))
    sc = ax.scatter(
        x, y,
        c=x, cmap="viridis",
        norm=make_true_flux_norm(x),
        s=18, alpha=0.75, edgecolors="none",
    )
    ax.axhline(0.0, color="red", ls="--", lw=1.6, alpha=0.9)

    ax.set_xscale("log")
    ax.set_xlabel("TRUE total detection flux", fontsize=13)
    ax.set_ylabel("Mean flux residual (Pred − True)", fontsize=13)
    ax.set_title("Per-object flux bias vs. TRUE total detection flux",
                 fontsize=14)
    ax.grid(alpha=0.25, which="both")

    cb = fig.colorbar(sc, ax=ax, pad=0.02)
    cb.set_label("TRUE total detection flux\n(log scale, 1–99%)", fontsize=11)

    fig.tight_layout()
    fig.savefig(output_directory / f"{filename}.png", dpi=300)
    fig.savefig(output_directory / f"{filename}.pdf")
    plt.close(fig)


# ------------------------------------------------------------------------------
# NEW PLOT 14: Flux-binned bias diagnostic (mean ± SEM, median)
# ------------------------------------------------------------------------------
def plot_flux_binned_bias(
    true_flux_per_obj, mean_residual_per_obj, output_directory,
    n_bins=20, filename="14_flux_binned_bias"
):
    """
    Binned diagnostic of flux residual vs TRUE flux.
    For each log-spaced flux bin, plot:
      - mean residual ± 1 SEM (with shaded band)
      - median residual (dashed line)
    """
    true_flux_per_obj = np.asarray(true_flux_per_obj, dtype=float)
    mean_residual_per_obj = np.asarray(mean_residual_per_obj, dtype=float)

    mask = (np.isfinite(true_flux_per_obj) &
            np.isfinite(mean_residual_per_obj) &
            (true_flux_per_obj > 0))
    if mask.sum() < 10:
        logger.warning("[plot_flux_binned_bias] Not enough points. Skipping.")
        return

    x = true_flux_per_obj[mask]
    y = mean_residual_per_obj[mask]

    # Log-spaced bin edges
    bin_edges = np.logspace(np.log10(x.min()), np.log10(x.max()), n_bins + 1)
    bin_centers = np.sqrt(bin_edges[:-1] * bin_edges[1:])  # geometric mean

    means = np.full(n_bins, np.nan)
    sems = np.full(n_bins, np.nan)
    medians = np.full(n_bins, np.nan)

    for i in range(n_bins):
        sel = (x >= bin_edges[i]) & (x < bin_edges[i + 1])
        n = sel.sum()
        if n >= 3:
            yi = y[sel]
            means[i] = np.mean(yi)
            medians[i] = np.median(yi)
            sems[i] = np.std(yi, ddof=1) / np.sqrt(n)

    valid = np.isfinite(means)

    fig, ax = plt.subplots(figsize=(12, 7))

    # Mean ± SEM
    ax.plot(bin_centers[valid], means[valid],
            "o-", color="#1f77b4", lw=2.0, ms=8,
            label="Mean residual", zorder=4)
    ax.fill_between(bin_centers[valid],
                    means[valid] - sems[valid],
                    means[valid] + sems[valid],
                    color="#1f77b4", alpha=0.20, label="±1 SEM", zorder=2)

    # Median
    ax.plot(bin_centers[valid], medians[valid],
            "s--", color="#ff7f0e", lw=2.0, ms=8,
            label="Median residual", zorder=5)

    # Reference line at 0
    ax.axhline(0.0, color="gray", ls="--", lw=1.2, alpha=0.8)

    ax.set_xscale("log")
    ax.set_xlabel("TRUE total detection flux", fontsize=13)
    ax.set_ylabel("Flux residual (Pred − True)", fontsize=13)
    ax.set_title("Flux-binned bias diagnostic using TRUE flux", fontsize=14)
    ax.grid(alpha=0.25, which="both")
    ax.legend(loc="lower left", fontsize=11, framealpha=0.95)

    fig.tight_layout()
    fig.savefig(output_directory / f"{filename}.png", dpi=300)
    fig.savefig(output_directory / f"{filename}.pdf")
    plt.close(fig)


# ------------------------------------------------------------------------------
# NEW PLOT 15/16: t-SNE coloured by transformed coordinates
# ------------------------------------------------------------------------------
def plot_tsne_by_coordinate(
    embedding_2d, ra_per_obj, dec_per_obj, output_directory,
    scale_mode="trig", bins=40
):
    """
    Generate t-SNE plots coloured by transformed celestial coordinates.

    Parameters
    ----------
    embedding_2d : (N_obj, 2) t-SNE coords.
    ra_per_obj   : (N_obj,) RA in degrees, or None.
    dec_per_obj  : (N_obj,) DEC in degrees, or None.
    scale_mode   : 'trig'  → uses sin(RA) and DEC/90 (normalised)
                   'raw'   → uses raw RA and DEC
    bins         : number of bins for the marginal histogram.
    """
    embedding_2d = np.asarray(embedding_2d)
    n_obj = embedding_2d.shape[0]

    # ---- sin(RA) plot ----
    if ra_per_obj is not None:
        ra = np.asarray(ra_per_obj, dtype=float)[:n_obj]
        if scale_mode == "trig":
            # sin(RA) requires RA in radians
            ra_transformed = np.sin(np.deg2rad(ra))
            label = "sin(RA)"
            title = "t-SNE of CLS embeddings — coloured by sin(RA)"
        else:
            ra_transformed = ra
            label = "RA (degrees)"
            title = "t-SNE of CLS embeddings — coloured by RA"

        # Use a non-dark background and 'viridis' cmap for coordinate plots
        _plot_tsne_coord(
            embedding_2d=embedding_2d,
            values=ra_transformed,
            label=label,
            title=title,
            filename="15_tsne_colored_by_sin_ra" if scale_mode == "trig"
                     else "15_tsne_colored_by_ra",
            output_directory=output_directory,
            bins=bins,
        )

    # ---- scaled DEC plot ----
    if dec_per_obj is not None:
        dec = np.asarray(dec_per_obj, dtype=float)[:n_obj]
        if scale_mode == "trig":
            # Simple normalisation: DEC ranges in [-90, 90]
            dec_transformed = dec / 90.0
            label = "DEC (model-scaled)"
            title = "t-SNE of CLS embeddings — coloured by scaled DEC"
        else:
            dec_transformed = dec
            label = "DEC (degrees)"
            title = "t-SNE of CLS embeddings — coloured by DEC"

        _plot_tsne_coord(
            embedding_2d=embedding_2d,
            values=dec_transformed,
            label=label,
            title=title,
            filename="16_tsne_colored_by_scaled_dec" if scale_mode == "trig"
                     else "16_tsne_colored_by_dec",
            output_directory=output_directory,
            bins=bins,
        )


def _plot_tsne_coord(
    embedding_2d, values, label, title, filename, output_directory,
    bins=40
):
    """
    Internal helper: t-SNE scatter coloured by a coordinate-like quantity.
    Uses a light background and 'viridis' cmap (matches reference figures).
    """
    embedding_2d = np.asarray(embedding_2d)
    values = np.asarray(values, dtype=float)

    if embedding_2d.shape[0] != values.shape[0]:
        raise ValueError(
            f"[_plot_tsne_coord] shape mismatch for '{filename}': "
            f"embedding_2d has {embedding_2d.shape[0]} rows but "
            f"values has {values.shape[0]} rows."
        )

    finite = np.isfinite(values)
    if finite.sum() < 2:
        logger.warning(f"[_plot_tsne_coord] Not enough finite values for '{filename}'.")
        return

    x = embedding_2d[finite, 0]
    y = embedding_2d[finite, 1]
    v = values[finite]

    fig, (ax_scatter, ax_hist) = plt.subplots(
        1, 2, figsize=(15, 6.5),
        gridspec_kw={"width_ratios": [3, 1], "wspace": 0.06},
    )

    # Light background
    ax_scatter.set_facecolor('white')

    sc = ax_scatter.scatter(
        x, y, c=v, cmap="viridis",
        s=14, alpha=0.85, edgecolors="none", zorder=2,
    )
    ax_scatter.set_xlabel("t-SNE component 1", fontsize=12)
    ax_scatter.set_ylabel("t-SNE component 2", fontsize=12)
    ax_scatter.set_title(title, loc="left", fontsize=13)
    ax_scatter.grid(alpha=0.15)

    cb = fig.colorbar(sc, ax=ax_scatter, pad=0.01, fraction=0.045)
    cb.set_label(label, fontsize=11)

    # Horizontal Marginal
    counts, bin_edges = np.histogram(v, bins=bins)
    percentages = (counts / len(v)) * 100
    bin_centers = (bin_edges[:-1] + bin_edges[1:]) / 2
    ax_hist.barh(bin_centers, percentages,
                 height=(bin_edges[1] - bin_edges[0]) * 0.85,
                 color="#4c78a8", alpha=0.9,
                 edgecolor="white", linewidth=0.3)
    ax_hist.set_xlabel("Fraction of objects (%)", fontsize=12)
    ax_hist.tick_params(labelleft=False)
    ax_hist.set_title("Marginal", fontsize=12)
    ax_hist.grid(alpha=0.15, axis="x")
    ax_hist.spines['top'].set_visible(False)
    ax_hist.spines['right'].set_visible(False)
    ax_hist.spines['left'].set_visible(False)

    fig.tight_layout()
    fig.savefig(output_directory / f"{filename}.png", dpi=300)
    fig.savefig(output_directory / f"{filename}.pdf")
    plt.close(fig)


# ==============================================================================
# Main Function
# ==============================================================================

def create_plots(history, results, output_directory, seed=42, dataset_metadata=None):
    """
    Generate all visualization plots.

    Parameters
    ----------
    history : object with train_losses, validation_losses, best_epoch
    results : dict with 'true' (N,2), 'predicted' (N,2), 'embeddings' (N_obj, D)
    output_directory : pathlib.Path
    seed : int
    dataset_metadata : dict with keys:
        - 'object_ids'      : (N_samples,) int
        - 'total_flux'      : (N_samples,) float
        - 'ra'              : (N_samples,) float
        - 'dec'             : (N_samples,) float
        - 'total_flux_obj'  : (N_obj,) float (optional)
        - 'ra_obj'          : (N_obj,) float (optional)
        - 'dec_obj'         : (N_obj,) float (optional)
    """
    output_directory.mkdir(parents=True, exist_ok=True)

    # --- PLOT 1: Loss curves ---
    figure, axis = plt.subplots(figsize=(10, 6))
    axis.plot(history.train_losses, label="Train loss", linewidth=2)
    axis.plot(history.validation_losses, label="Validation loss", linewidth=2)
    if history.best_epoch >= 0:
        axis.axvline(history.best_epoch, color="green", linestyle="--",
                     label=f"Best epoch ({history.best_epoch + 1})")
    axis.set(xlabel="Epoch", ylabel="Loss", title="Training and Validation Loss")
    axis.legend()
    axis.grid(alpha=0.3)
    figure.tight_layout()
    figure.savefig(output_directory / "01_loss_curves.png", dpi=300)
    plt.close(figure)

    # --- PLOT 2: Reconstruction scatter ---
    true_values = results["true"]
    predicted_values = results["predicted"]
    figure, axes = plt.subplots(1, 2, figsize=(12, 5))
    for feature, name in enumerate(("Flux", "Error")):
        axes[feature].scatter(true_values[:, feature], predicted_values[:, feature],
                              s=3, alpha=0.1)
        lower = min(true_values[:, feature].min(), predicted_values[:, feature].min())
        upper = max(true_values[:, feature].max(), predicted_values[:, feature].max())
        axes[feature].plot([lower, upper], [lower, upper], "r--", linewidth=2)
        axes[feature].set(xlabel=f"True {name} (arcsinh)",
                          ylabel=f"Predicted {name} (arcsinh)",
                          title=f"{name}: True vs Predicted")
        axes[feature].grid(alpha=0.3)
    figure.tight_layout()
    figure.savefig(output_directory / "02_reconstruction_scatter.png", dpi=300)
    plt.close(figure)

    # --- PLOT 3: Residual histograms ---
    residuals = predicted_values - true_values
    figure, axes = plt.subplots(1, 2, figsize=(12, 5))
    for feature, name in enumerate(("Flux", "Error")):
        axes[feature].hist(residuals[:, feature], bins=100, alpha=0.75)
        axes[feature].axvline(0, color="red", linestyle="--")
        axes[feature].set(xlabel="Predicted − true", ylabel="Count",
                          title=f"{name} Residuals")
    figure.tight_layout()
    figure.savefig(output_directory / "03_residual_histograms.png", dpi=300)
    plt.close(figure)

    # --- PLOT 4: Basic t-SNE ---
    embeddings = results["embeddings"]
    projected = None
    if len(embeddings) > 30:
        perplexity = min(30, max(5, (len(embeddings) - 1) // 3))
        projected = TSNE(n_components=2, random_state=seed,
                         perplexity=perplexity).fit_transform(embeddings)
        figure, axis = plt.subplots(figsize=(9, 8))
        axis.scatter(projected[:, 0], projected[:, 1], s=15, alpha=0.6)
        axis.set(title="t-SNE of CLS Embeddings")
        figure.tight_layout()
        figure.savefig(output_directory / "04_tsne_cls_embeddings.png", dpi=300)
        plt.close(figure)
        logger.info("PLOT 4 (basic t-SNE) generated.")
    else:
        logger.warning("PLOT 4 skipped: too few embeddings (<=30).")

    # ============================================================
    # PER-OBJECT DIAGNOSTICS
    # ============================================================
    if dataset_metadata is None:
        logger.info("dataset_metadata not provided. Skipping plots 5-16.")
        logger.info(f"All plots saved to: {output_directory}")
        return

    object_ids = dataset_metadata.get('object_ids')
    total_flux_sample = dataset_metadata.get('total_flux')
    ra_sample = dataset_metadata.get('ra')
    dec_sample = dataset_metadata.get('dec')

    if object_ids is None:
        logger.info("object_ids missing. Skipping plots 5-16.")
        logger.info(f"All plots saved to: {output_directory}")
        return

    # ---- Aggregate per-object R² and mean flux ----
    logger.info("Calculating R² per object...")
    unique_objects = np.unique(object_ids)

    r2_flux_per_obj = []
    r2_error_per_obj = []
    flux_per_object = []
    mean_residual_per_object = []

    for obj_id in unique_objects:
        mask = object_ids == obj_id
        if mask.sum() < 2:
            continue
        true_flux_obj = true_values[mask, 0]
        pred_flux_obj = predicted_values[mask, 0]
        true_err_obj = true_values[mask, 1]
        pred_err_obj = predicted_values[mask, 1]

        r2_flux_per_obj.append(r2_safe(true_flux_obj, pred_flux_obj))
        r2_error_per_obj.append(r2_safe(true_err_obj, pred_err_obj))
        mean_residual_per_object.append(
            float(np.mean(pred_flux_obj - true_flux_obj))
        )
        if total_flux_sample is not None:
            flux_per_object.append(
                float(np.mean(np.asarray(total_flux_sample)[mask]))
            )

    r2_flux_per_obj = np.array(r2_flux_per_obj, dtype=float)
    r2_error_per_obj = np.array(r2_error_per_obj, dtype=float)
    mean_residual_per_object = np.array(mean_residual_per_object, dtype=float)
    flux_per_object = (np.array(flux_per_object, dtype=float)
                       if flux_per_object else None)

    # --- PLOT 5: R² distribution histogram ---
    finite_r2 = r2_flux_per_obj[np.isfinite(r2_flux_per_obj)]
    if len(finite_r2) > 0:
        figure, axis = plt.subplots(figsize=(10, 6))
        axis.hist(finite_r2, bins=50, alpha=0.75, edgecolor='black', label='Flux R²')
        axis.axvline(0, color='red', linestyle='--', linewidth=2, label='R² = 0')
        axis.axvline(np.mean(finite_r2), color='green', linestyle='-',
                     linewidth=2, label=f'Mean R² = {np.mean(finite_r2):.3f}')
        axis.set(xlabel='R² per Object', ylabel='Number of Objects',
                 title=f'R² Distribution per Object (N={len(finite_r2)})')
        axis.legend()
        axis.grid(alpha=0.3)
        figure.tight_layout()
        figure.savefig(output_directory / "05_r2_per_object_histogram.png", dpi=300)
        plt.close(figure)
        logger.info("PLOT 5 (R² histogram) generated.")

    # --- PLOT 6: Per-object Flux R² scatter diagnostic ---
    if flux_per_object is not None:
        valid_6 = (np.isfinite(r2_flux_per_obj) & np.isfinite(flux_per_object)
                   & (flux_per_object > 0))
        if valid_6.sum() >= 10:
            plot_r2_scatter_diagnostic(
                y_values=r2_flux_per_obj[valid_6],
                true_flux=flux_per_object[valid_6],
                n_val=int(valid_6.sum()),
                y_label=r"Per-object \(R^2\) — reconstructed flux",
                panel_letter="a",
                filename="06_per_object_R2_flux_diagnostic",
                output_directory=output_directory,
            )
            logger.info("PLOT 6 (Flux R² diagnostic) generated.")

    # --- PLOT 7: Per-object Error R² scatter diagnostic ---
    if flux_per_object is not None:
        valid_7 = (np.isfinite(r2_error_per_obj) & np.isfinite(flux_per_object)
                   & (flux_per_object > 0))
        if valid_7.sum() >= 10:
            plot_r2_scatter_diagnostic(
                y_values=r2_error_per_obj[valid_7],
                true_flux=flux_per_object[valid_7],
                n_val=int(valid_7.sum()),
                y_label=r"Per-object \(R^2\) — reconstructed flux error",
                panel_letter="b",
                filename="07_per_object_R2_error_diagnostic",
                output_directory=output_directory,
            )
            logger.info("PLOT 7 (Error R² diagnostic) generated.")

    # --- PLOT 8: Bias vs flux (existing linear-trend version) ---
    if flux_per_object is not None:
        valid_8 = (np.isfinite(flux_per_object)
                   & np.isfinite(mean_residual_per_object))
        if valid_8.sum() > 2:
            fpr = flux_per_object[valid_8]
            mrp = mean_residual_per_object[valid_8]
            figure, axis = plt.subplots(figsize=(10, 8))
            scatter = axis.scatter(fpr, mrp, c=fpr, cmap='inferno',
                                   s=30, alpha=0.7, edgecolors='black',
                                   linewidth=0.5)
            cbar = figure.colorbar(scatter, ax=axis)
            cbar.set_label('Total Flux (arcsinh)', fontsize=12)
            axis.axhline(0, color='red', linestyle='--', linewidth=2, alpha=0.7)
            if np.ptp(fpr) > 0:
                z = np.polyfit(fpr, mrp, 1)
                p = np.poly1d(z)
                axis.plot(np.sort(fpr), p(np.sort(fpr)),
                          "r-", linewidth=2, label=f'Trend: slope={z[0]:.4f}')
                axis.legend()
            axis.set(xlabel='Total Flux per Object (arcsinh)',
                     ylabel='Mean Residual (Predicted - True) per Object',
                     title=f'Bias vs Total Flux (N={len(mrp)})')
            axis.grid(alpha=0.3)
            figure.tight_layout()
            figure.savefig(output_directory / "08_bias_vs_flux.png", dpi=300)
            plt.close(figure)
            logger.info("PLOT 8 (bias vs flux) generated.")

    # ============================================================
    # PLOTS 9-12: t-SNE coloured by RA, DEC, flux (PER-OBJECT arrays)
    # ============================================================
    if projected is None:
        logger.warning("t-SNE plots 9-12 skipped: no 2D projection available.")
        logger.info(f"All plots saved to: {output_directory}")
        return

    flux_obj = dataset_metadata.get('total_flux_obj')
    ra_obj = dataset_metadata.get('ra_obj')
    dec_obj = dataset_metadata.get('dec_obj')

    if flux_obj is None and total_flux_sample is not None:
        flux_obj, _ = _aggregate_per_object(object_ids, total_flux_sample)
    if ra_obj is None and ra_sample is not None:
        ra_obj, _ = _aggregate_per_object(object_ids, ra_sample)
    if dec_obj is None and dec_sample is not None:
        dec_obj, _ = _aggregate_per_object(object_ids, dec_sample)

    if flux_obj is not None:
        flux_obj = np.asarray(flux_obj, dtype=float)
    if ra_obj is not None:
        ra_obj = np.asarray(ra_obj, dtype=float)
    if dec_obj is not None:
        dec_obj = np.asarray(dec_obj, dtype=float)

    n_obj = len(projected)
    if flux_obj is not None:
        flux_obj = flux_obj[:n_obj]
    if ra_obj is not None:
        ra_obj = ra_obj[:n_obj]
    if dec_obj is not None:
        dec_obj = dec_obj[:n_obj]

    # --- PLOT 9: t-SNE by raw RA ---
    if ra_obj is not None and len(ra_obj) == n_obj:
        plot_tsne_with_marginal(
            embedding_2d=projected,
            colour_values=ra_obj,
            label="RA (degrees)",
            filename="09_tsne_colored_by_ra",
            output_directory=output_directory,
            flux_scale=False,
        )
        logger.info("PLOT 9 (t-SNE by RA) generated.")

    # --- PLOT 10: t-SNE by raw DEC ---
    if dec_obj is not None and len(dec_obj) == n_obj:
        plot_tsne_with_marginal(
            embedding_2d=projected,
            colour_values=dec_obj,
            label="DEC (degrees)",
            filename="10_tsne_colored_by_dec",
            output_directory=output_directory,
            flux_scale=False,
        )
        logger.info("PLOT 10 (t-SNE by DEC) generated.")

    # --- PLOT 11: t-SNE by Total Flux ---
    if flux_obj is not None and len(flux_obj) == n_obj:
        plot_tsne_with_marginal(
            embedding_2d=projected,
            colour_values=flux_obj,
            label="Total Flux (arcsinh)",
            filename="11_tsne_colored_by_flux",
            output_directory=output_directory,
            flux_scale=True,
        )
        logger.info("PLOT 11 (t-SNE by flux) generated.")

    # --- PLOT 12: 3D t-SNE by Flux ---
    if flux_obj is not None and len(flux_obj) == n_obj and n_obj > 30:
        perplexity = min(30, max(5, (n_obj - 1) // 3))
        tsne_3d = TSNE(n_components=3, random_state=seed, perplexity=perplexity)
        projected_3d = tsne_3d.fit_transform(embeddings)
        plot_3d_tsne(
            embedding_3d=projected_3d,
            true_flux=flux_obj,
            output_directory=output_directory,
            filename="12_tsne_3d_flux",
        )
        logger.info("PLOT 12 (3D t-SNE) generated.")

    # ============================================================
    # NEW: PLOTS 13-16
    # ============================================================
    if flux_per_object is not None and len(flux_per_object) > 0:
        # --- PLOT 13: Per-object bias vs TRUE flux ---
        plot_per_object_bias_vs_true_flux(
            true_flux_per_obj=flux_per_object,
            mean_residual_per_obj=mean_residual_per_object,
            output_directory=output_directory,
            filename="13_per_object_bias_vs_true_flux",
        )
        logger.info("PLOT 13 (per-object bias vs TRUE flux) generated.")

        # --- PLOT 14: Flux-binned bias diagnostic ---
        plot_flux_binned_bias(
            true_flux_per_obj=flux_per_object,
            mean_residual_per_obj=mean_residual_per_object,
            output_directory=output_directory,
            n_bins=20,
            filename="14_flux_binned_bias",
        )
        logger.info("PLOT 14 (flux-binned bias) generated.")

    # --- PLOTS 15-16: t-SNE by sin(RA) and scaled DEC ---
    plot_tsne_by_coordinate(
        embedding_2d=projected,
        ra_per_obj=ra_obj,
        dec_per_obj=dec_obj,
        output_directory=output_directory,
        scale_mode="trig",
        bins=40,
    )
    logger.info("PLOTS 15 & 16 (sin(RA) and scaled DEC t-SNE) attempted.")

    logger.info(f"All plots saved to: {output_directory}")
